-- ============================================================
-- 003 — Drill seed, part 03 of 07  (40 drills)
--
-- Paste into the Supabase SQL editor and run. Parts are independent and
-- idempotent: re-running one updates those rows rather than duplicating them.
--
-- Requires scripts/002_drill_content.sql to have been applied first.
-- ============================================================

INSERT INTO public.drills (
  slug, name, category, subcategory, type, level, duration_min, player_count, group_size, description, objective, setup, instructions, coaching_cues, common_errors, variations, tags, diagram_type, diagram_data
) VALUES
  ('FW-016', 'Hexagon Drill: 360-Degree Agility', 'Footwork', 'Agility', 'footwork', 'intermediate', 10, 1, 'individual', 'Build multidirectional agility and balance through the hexagon drill — the most comprehensive single-player footwork exercise for tennis. The hexagon forces the body to move and change direction in 6 different directions, testing every movement plane used in match play. It also builds proprioception — the body''s awareness of its position in space — which is essential for recovering balance after extreme positions.', 'Build multidirectional agility and balance through the hexagon drill — the most comprehensive single-player footwork exercise for tennis. The hexagon forces the body to move and change direction in 6 different directions, testing every movement plane used in match play. It also builds proprioception — the body''s awareness of its position in space — which is essential for recovering balance after extreme positions.', 'Create a hexagon on the court using tape or cones — 6 sides, each 2 feet long. Player 1 stands inside the hexagon and jumps in and out of each side consecutively, rotating around the hexagon.', ARRAY['Create a hexagon with 2-foot sides centered on the baseline.','Player 1 stands inside the hexagon.','Jump out over side 1, jump back in. Jump out over side 2, jump back in. Continue around all 6 sides.','Complete the full hexagon in one direction, then reverse.','Time the completion of one full hexagon rotation. Target: under 10 seconds. Rest 30 seconds. Repeat 5 times.']::text[], ARRAY['Two-foot jumps — both feet leave and land together on each jump.','Face forward at all times — don''t turn to face each side.','Absorb each landing on the balls of the feet — quiet landing means good absorption.','Arms drive each jump — use them for power and balance.','Minimize time on the ground — the goal is explosive re-launch after each landing.']::text[], ARRAY['Turning the body to face each side — must stay facing the same direction throughout.','Heel landings — significantly slows re-launch time.','Sloppy shape — missing the sides of the hexagon defeats the drill.']::text[], ARRAY['Single-leg hexagon: one leg only — extreme balance and proprioception challenge.','Eyes closed hexagon: train the proprioceptive component without visual aid.','Racket hexagon: hold the racket throughout — adds the real-game equipment challenge.']::text[], ARRAY['footwork','hexagon','agility','intermediate','balance','multidirectional']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":820},{"x1":200,"y1":820,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":225,"y2":825},{"x1":225,"y1":825,"x2":200,"y2":850}],"areas":[{"x":200,"y":845,"r":30}]}'::jsonb),
  ('FW-017', 'Net Approach Footwork: T-Position Closing', 'Footwork', 'Net Footwork', 'footwork', 'intermediate', 12, 2, 'pairs', 'Train the net approach footwork sequence — specifically the split step position and closing movement that a net player uses to cut off passing angles. Many net players take a static position and wait for the ball to come to them. Elite net players are constantly moving: closing toward the ball, split stepping before each pass, and moving diagonally forward with each volley. This drill trains that active, dynamic net footwork.', 'Train the net approach footwork sequence — specifically the split step position and closing movement that a net player uses to cut off passing angles. Many net players take a static position and wait for the ball to come to them. Elite net players are constantly moving: closing toward the ball, split stepping before each pass, and moving diagonally forward with each volley. This drill trains that active, dynamic net footwork.', 'Player 1 starts at the T (center service line and service line intersection). Player 2 hits balls from the baseline. Player 1 must split step, close toward the ball diagonally, volley, and recover to T position after every ball.', ARRAY['Player 1 starts at the T position — at the service line center.','Player 2 hits a ball to Player 1''s forehand volley side.','Player 1 split steps, takes one diagonal step forward toward the ball, volleys.','Player 1 recovers to the T position.','Player 2 immediately hits to the backhand side — Player 1 repeats. Continue for 10 exchanges, rest 30 seconds.']::text[], ARRAY['After each split step, step diagonally forward toward the ball — never backward.','Close the net with each volley — the T position should gradually move closer to the net.','Recover to T position quickly after each volley — the T is the default volley position.','Step into every volley — passive waiting produces weak, floated volleys.','The split step at the T is the foundation — without it, the diagonal step is impossible.']::text[], ARRAY['Standing still at T — waiting for the ball instead of closing toward it.','No recovery to T after the volley — drifts out of position.','No split step — must happen before every volley.']::text[], ARRAY['Rapid-fire T position: Player 2 hits faster — Player 1 must split step and close more quickly.','Move T closer: after 10 exchanges, Player 1 moves to mid-service box — shorter distances, sharper angles.','T position with lobs: Player 2 occasionally lobs — Player 1 must retreat instead of closing.']::text[], ARRAY['footwork','net','T position','intermediate','closing','split step']::text[], 'json', '{"p1":{"x":200,"y":640},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":640,"x2":280,"y2":600},{"x1":280,"y1":600,"x2":200,"y2":640},{"x1":200,"y1":640,"x2":120,"y2":600},{"x1":120,"y1":600,"x2":200,"y2":640}],"shots":[{"x1":200,"y1":70,"x2":285,"y2":610},{"x1":200,"y1":60,"x2":115,"y2":610}],"areas":[{"x":200,"y":640,"r":20}]}'::jsonb),
  ('FW-018', 'Deceleration and Plant: Stopping Under Control', 'Footwork', 'Deceleration', 'footwork', 'intermediate', 10, 2, 'pairs', 'Develop controlled deceleration — the ability to sprint to a ball and stop under control for the shot. Many players arrive at the ball but cannot stop properly — they over-run, stumble, or their momentum carries them past the ideal contact point. Controlled deceleration allows the player to arrive in balance, hit a quality shot, and immediately redirect. This is the difference between reaching the ball and being in position to hit the ball.', 'Develop controlled deceleration — the ability to sprint to a ball and stop under control for the shot. Many players arrive at the ball but cannot stop properly — they over-run, stumble, or their momentum carries them past the ideal contact point. Controlled deceleration allows the player to arrive in balance, hit a quality shot, and immediately redirect. This is the difference between reaching the ball and being in position to hit the ball.', 'Player 2 feeds balls to various positions with a cone marking the ideal arrival point for each shot. Player 1 must sprint to the cone, stop under control, and hit the shot from the exact cone position.', ARRAY['Player 2 places a cone at the ideal contact position for each shot (wide forehand, wide backhand, short ball).','Player 2 feeds the ball — Player 1 must sprint and stop with their dominant foot on the cone.','Player 1 hits the shot from the planted position on the cone.','If Player 1 over-runs the cone or under-runs it, the repetition is repeated.','Play 15 repetitions per cone position. 3 positions total.']::text[], ARRAY['Read the distance early — start the deceleration process before arriving, not at the cone.','Lower your center of gravity in the last 2 steps — dropping the hips decelerates the body.','Plant the dominant foot — this is the anchor for both the shot and the direction change.','Don''t over-run by reaching — take one fewer step and stretch if needed.','Deceleration is a skill — it requires training, not just instinct.']::text[], ARRAY['Over-running the cone — momentum carries past the ideal contact point.','Under-running and reaching — the arm stretches to compensate for under-running.','No deceleration — arriving at full sprint and trying to hit is unstable.']::text[], ARRAY['Cones without balls: Player 1 sprints to cones from center and plants — pure deceleration training.','Variable cone distance: Player 2 moves the cone between repetitions — Player 1 reads and adjusts.','Deceleration to direction change: plant at the cone, immediately sprint to a second cone.']::text[], ARRAY['footwork','deceleration','plant','intermediate','balance','control']::text[], 'json', '{"p1":{"x":310,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":310,"y2":850}],"shots":[{"x1":200,"y1":490,"x2":315,"y2":840},{"x1":308,"y1":845,"x2":100,"y2":100}],"cones":[{"x":310,"y":850}]}'::jsonb),
  ('FW-019', '5-Point Star Footwork: Baseline Coverage Pattern', 'Footwork', 'Court Coverage', 'footwork', 'intermediate', 12, 2, 'pairs', 'Build comprehensive baseline coverage through a structured 5-point movement pattern that visits every key baseline position. The 5-point star covers: center, wide forehand, wide backhand, deep forehand, and deep backhand — the five most important position zones for baseline play. Training this specific pattern develops the automatic ability to navigate every corner of the baseline efficiently.', 'Build comprehensive baseline coverage through a structured 5-point movement pattern that visits every key baseline position. The 5-point star covers: center, wide forehand, wide backhand, deep forehand, and deep backhand — the five most important position zones for baseline play. Training this specific pattern develops the automatic ability to navigate every corner of the baseline efficiently.', 'Place cones at 5 positions: center baseline, wide left (doubles alley level), wide right, 3 feet left of center, 3 feet right of center. Player 2 calls or points to positions. Player 1 must move from center to each called position, shadow swing, and return to center.', ARRAY['Player 1 starts at center baseline (cone 1).','Player 2 calls a cone number — Player 1 sprints to that cone, shadow swings, and returns to center.','Player 2 calls the next cone while Player 1 is still recovering — no rest between cones.','Continue for 30 seconds of continuous movement. Rest 45 seconds. Repeat 5 rounds.','Vary the calling speed — sometimes fast, sometimes slow — to test recovery speed.']::text[], ARRAY['Center cone is home — always return to center before the next call.','Different movement for different cones: lateral shuffle for short distances, crossover for wide ones.','Shadow swing at every cone — the drill is footwork AND shot simulation.','Read the next call while recovering — anticipate rather than react.','Track your recovery speed: are you arriving at center before the next call?']::text[], ARRAY['Not returning to center between cones — must always return home.','Shuffling to wide cones — must use crossover steps for the wide cones.','Slow shadow swing — the swing should be quick and realistic, not slow and deliberate.']::text[], ARRAY['Real balls at each cone: Player 2 feeds a real ball to each called cone — Player 1 hits.','7-cone version: add 2 more cones for deep angled positions.','Randomized speed: Player 2 calls slowly for 10 seconds then rapidly for 10 seconds — alternating.']::text[], ARRAY['footwork','star pattern','court coverage','intermediate','baseline','movement']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":65,"y2":850},{"x1":65,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":335,"y2":850},{"x1":335,"y1":850,"x2":200,"y2":850}],"cones":[{"x":200,"y":850},{"x":65,"y":850},{"x":335,"y":850},{"x":130,"y":850},{"x":270,"y":850}]}'::jsonb),
  ('FW-020', 'Serve Footwork: Trophy Position to Contact', 'Footwork', 'Serve Footwork', 'footwork', 'beginner', 10, 1, 'individual', 'Isolate and train the serve footwork — specifically the weight transfer from the back foot to the front foot through the trophy position to contact. The serve is a full-body movement that begins from the feet, and most power and consistency problems on the serve stem from incorrect weight transfer timing. This drill builds the serve footwork in isolation before the full serve is assembled.', 'Isolate and train the serve footwork — specifically the weight transfer from the back foot to the front foot through the trophy position to contact. The serve is a full-body movement that begins from the feet, and most power and consistency problems on the serve stem from incorrect weight transfer timing. This drill builds the serve footwork in isolation before the full serve is assembled.', 'Player 1 stands at the baseline in the serving stance. No ball is used. Player 1 performs the serve motion in slow motion, pausing at each key footwork position: ready stance, trophy position, launch, follow-through.', ARRAY['Player 1 stands in the serving stance: feet shoulder-width apart, front foot at 45 degrees to the baseline.','Shift weight to the back foot while raising the tossing arm — this is the coiling phase.','Rise to the trophy position: front leg bent, back leg pushing up, body arched.','Drive upward from both legs — heels leave the ground simultaneously.','Follow through and land on the front foot — weight has completely transferred.','Repeat 20 times in slow motion, then 20 at normal speed. Focus entirely on the feet.']::text[], ARRAY['Weight starts on both feet, transfers to the back foot, then drives through to the front foot.','Both heels come off the ground at contact — the serve is a jump.','Land on the front foot — if landing on both feet, the leg drive was incomplete.','The front foot pivots as the weight transfers — don''t keep it locked.','Film from the side: you should see both heels leaving the ground at contact.']::text[], ARRAY['Flat feet throughout — never getting on the toes prevents proper leg drive.','Landing on the back foot — body stayed behind instead of driving through.','No pivot on the front foot — causes the hip turn to be blocked.']::text[], ARRAY['Slow-motion in front of a mirror: check each footwork position visually.','Add the full serve: once footwork is correct in isolation, add the swing.','Film comparison: film the footwork in isolation and with the full serve — check if they match.']::text[], ARRAY['footwork','serve','weight transfer','beginner','technique','foundation']::text[], 'json', '{"p1":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":380}],"areas":[{"x":240,"y":860,"r":20}]}'::jsonb),
  ('FW-021', 'Two-Cone Reactive Shuffle: Read and React', 'Footwork', 'Reactive Movement', 'footwork', 'intermediate', 10, 2, 'pairs', 'Build reactive lateral movement speed through a two-cone drill with unpredictable direction cues. Unlike a structured shuffle drill where the pattern is known, this drill adds the element of visual reaction — the player doesn''t know which direction is coming. This directly trains the split step-to-first-step reaction sequence that occurs on every groundstroke in a match.', 'Build reactive lateral movement speed through a two-cone drill with unpredictable direction cues. Unlike a structured shuffle drill where the pattern is known, this drill adds the element of visual reaction — the player doesn''t know which direction is coming. This directly trains the split step-to-first-step reaction sequence that occurs on every groundstroke in a match.', 'Two cones placed 6 feet apart centered on the baseline. Player 2 stands facing Player 1 and points left or right randomly. Player 1 must shuffle to the pointed side cone, touch it, and shuffle back to center before the next direction is given.', ARRAY['Player 1 stands between two cones 6 feet apart centered on the baseline.','Player 2 points left or right randomly — as soon as the point is visible, Player 1 moves.','Player 1 shuffles to the pointed cone, touches it, and shuffles back to center.','Player 2 points the next direction while Player 1 is recovering — continuous pressure.','Continue for 20 seconds of movement, 20 seconds rest. Repeat 6 rounds.']::text[], ARRAY['Eyes on Player 2''s pointing hand — this is the reaction cue.','First movement must be immediate — no hesitation between the point and the first step.','Push off the center foot to initiate — don''t wait to be in the direction before pushing.','Keep low throughout — even during the recovery, don''t stand up.','The recovery must reach center — touching the center cone or mark between each shuffle.']::text[], ARRAY['Anticipating the direction — guessing before Player 2 points.','Slow first reaction — waiting for the full arm to extend before moving.','Not fully reaching center between shuffles — builds bad recovery habits.']::text[], ARRAY['Three-cone version: center, left, and right — Player 2 can point to any of the three.','Increase cone distance: 8, 10, 12 feet apart — more ground to cover per reaction.','Sound cue: Player 2 calls ''left'' or ''right'' with eyes closed — trains auditory reaction speed.']::text[], ARRAY['footwork','reactive','shuffle','intermediate','reading','lateral']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":290,"y2":850},{"x1":290,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":110,"y2":850}],"cones":[{"x":290,"y":850},{"x":110,"y":850}]}'::jsonb),
  ('FW-022', 'Net to Baseline: Transitioning Under Pressure', 'Footwork', 'Transition Footwork', 'footwork', 'intermediate', 12, 2, 'pairs', 'Train the transition footwork from the net to the baseline — used when a lob forces the net player to retreat. This is one of the least-practiced but most important movement sequences in tennis. Many players get lobbed and freeze or backpedal slowly, giving up the point without a fight. Elite players turn, use crossover steps, reach the ball, and often lob back or even smash — all while under maximum movement pressure.', 'Train the transition footwork from the net to the baseline — used when a lob forces the net player to retreat. This is one of the least-practiced but most important movement sequences in tennis. Many players get lobbed and freeze or backpedal slowly, giving up the point without a fight. Elite players turn, use crossover steps, reach the ball, and often lob back or even smash — all while under maximum movement pressure.', 'Player 1 starts at the net. Player 2 alternates between passing shots and lobs. On a passing shot, Player 1 volleys. On a lob, Player 1 retreats to the baseline using crossover steps and plays the ball.', ARRAY['Player 1 positions at the net.','Player 2 hits either a passing shot or a lob — Player 1 must read which.','Passing shot: Player 1 split steps and volleys.','Lob: Player 1 immediately turns sideways and retreats to play the ball.','After retreating and playing the ball, Player 1 must recover back to the net. Play each as a full point.']::text[], ARRAY['Lob recognition: the ball rises above Player 1''s reaching height within the first 10 feet of flight.','On lob recognition: immediate 180-degree turn, crossover steps backward.','Don''t give up on the point after being lobbed — fight for every ball.','After playing the lob retrieval: the server is likely at the net — Player 1 must lob back or pass.','Recovery to net after the lob retrieval is optional — judge based on court position.']::text[], ARRAY['Slow lob recognition — watching the ball go over instead of immediately retreating.','Backpedaling instead of crossover retreating — slow and unstable.','Giving up after being lobbed — missing the recovery lob or groundstroke.']::text[], ARRAY['Lob only: Player 2 only lobs — Player 1 practices the retreat movement repeatedly.','Retreat and smash: Player 2 lobs short enough for Player 1 to retreat and overhead.','Transition competition: Player 2 scores for every lob winner, Player 1 scores for every retrieval.']::text[], ARRAY['footwork','transition','net to baseline','intermediate','lob','retreat']::text[], 'json', '{"p1":{"x":200,"y":780},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":520,"x2":200,"y2":780}],"shots":[{"x1":200,"y1":70,"x2":200,"y2":520},{"x1":200,"y1":70,"x2":200,"y2":600},{"x1":200,"y1":775,"x2":200,"y2":100}],"areas":[{"x":200,"y":780,"r":25}]}'::jsonb),
  ('FW-023', 'Around the Court: Continuous Sprint Sequence', 'Footwork', 'Court Coverage', 'footwork', 'advanced', 12, 1, 'individual', 'Build maximum aerobic and anaerobic court coverage fitness through a continuous around-the-court sprint sequence. Unlike the spider run which returns to center, this drill has no home base — the player sprints continuously from point to point around the perimeter and interior of the court. It builds the specific endurance needed to sustain quality footwork in the third set of a long match.', 'Build maximum aerobic and anaerobic court coverage fitness through a continuous around-the-court sprint sequence. Unlike the spider run which returns to center, this drill has no home base — the player sprints continuously from point to point around the perimeter and interior of the court. It builds the specific endurance needed to sustain quality footwork in the third set of a long match.', 'Mark 8 cones around the court: two baseline corners, two net corners, two service line corners, and two service box centers. Player 1 sprints from cone to cone in sequence, touching each cone.', ARRAY['Place 8 cones: deuce baseline corner, ad baseline corner, deuce net post, ad net post, deuce service box center, ad service box center, deuce service line mid, ad service line mid.','Player 1 sprints from cone 1 to cone 2 to cone 3 and so on, touching each cone.','Complete the full 8-cone circuit without stopping.','Rest 90 seconds. Repeat 4 rounds. Track time per round.']::text[], ARRAY['Use the most efficient footwork for each segment — crossover for diagonals, sprint for straights.','Touch each cone with the hand closest to it — forces a full lean and direction change.','Breathe rhythmically — one breath per 3-4 strides maintains oxygen flow.','As fatigue builds, concentrate on foot placement — it degrades under fatigue first.','The last lap should be as fast as the first — if it''s slower, build fitness first.']::text[], ARRAY['Wide arcs around cones — saves energy but doesn''t replicate match footwork.','Slowing on the straight segments — all segments should be at full sprint.','Poor breathing — causes premature fatigue.']::text[], ARRAY['Shadow swing at each cone: simulate a shot before moving to the next cone.','Partner race: two players go simultaneously — creates competitive pressure.','Circuit with ball: Player 2 feeds a real ball at each cone — sprint, hit, sprint to next cone.']::text[], ARRAY['footwork','court coverage','sprint','advanced','endurance','fitness']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":65,"y1":850,"x2":335,"y2":850},{"x1":335,"y1":850,"x2":335,"y2":480},{"x1":335,"y1":480,"x2":65,"y2":480},{"x1":65,"y1":480,"x2":65,"y2":850}],"cones":[{"x":65,"y":850},{"x":335,"y":850},{"x":335,"y":480},{"x":65,"y":480},{"x":200,"y":640},{"x":200,"y":850}]}'::jsonb),
  ('FW-024', 'Serve and Recovery: Baseline Position After Serving', 'Footwork', 'Serve Footwork', 'footwork', 'beginner', 10, 2, 'pairs', 'Train the recovery footwork after the serve — getting back to the optimal baseline position before the return arrives. Most players serve and stand frozen where they served, which leaves them in poor position for the plus-one. The serve follow-through often leaves the player off-center or behind the baseline. This drill trains the automatic recovery to center baseline immediately after the serve.', 'Train the recovery footwork after the serve — getting back to the optimal baseline position before the return arrives. Most players serve and stand frozen where they served, which leaves them in poor position for the plus-one. The serve follow-through often leaves the player off-center or behind the baseline. This drill trains the automatic recovery to center baseline immediately after the serve.', 'Player 1 serves from both courts. A cone marks the optimal recovery position — center baseline, 1 foot behind the baseline. Player 1 must touch the cone after every serve before Player 2''s return arrives.', ARRAY['Player 1 serves from the deuce court.','Immediately after the serve follow-through, Player 1 sprints to the center baseline cone.','Player 2 hits a slow return — Player 1 must reach the cone before the return bounces.','After 10 serves from the deuce court, switch to the ad court.','Track: how many times does Player 1 reach the cone before the return bounces?']::text[], ARRAY['The serve follow-through ends — the recovery begins simultaneously. No pause.','Sprint to center, not shuffle — the return arrives quickly.','The landing foot after the serve (front foot) is already in the forward direction — use it to launch.','If the serve is wide or T, the recovery distance to center changes — adjust accordingly.','A player who serves and stands gives away their position before the rally starts.']::text[], ARRAY['Watching the serve flight instead of recovering — loses 1-2 full seconds.','Slow walk to center instead of sprint — return arrives before position is reached.','Not returning to center — stopping where the serve landed.']::text[], ARRAY['Serve and attack: Player 1 serves, recovers to center, then attacks the short return.','Serve to different positions: each serve location (T, wide, body) requires a different recovery distance.','Serve return game: play full points — Player 1 must recover to center on every serve.']::text[], ARRAY['footwork','serve','recovery','center baseline','beginner','positioning']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":120,"y":60},"moves":[{"x1":240,"y1":855,"x2":200,"y2":848}],"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":120,"y1":70,"x2":245,"y2":820}],"cones":[{"x":200,"y":850}]}'::jsonb),
  ('FW-025', 'Footwork Under Fatigue: The Third Set Drill', 'Footwork', 'Fatigue Footwork', 'footwork', 'advanced', 15, 2, 'pairs', 'Train footwork quality under genuine physical fatigue — the most honest footwork test available. Most footwork drills are done when fresh, but matches are often decided in the third set when legs are tired and footwork degrades. This drill uses a physical load before every footwork sequence, forcing players to maintain movement quality despite fatigue. The players who maintain their footwork under fatigue win more close matches.', 'Train footwork quality under genuine physical fatigue — the most honest footwork test available. Most footwork drills are done when fresh, but matches are often decided in the third set when legs are tired and footwork degrades. This drill uses a physical load before every footwork sequence, forcing players to maintain movement quality despite fatigue. The players who maintain their footwork under fatigue win more close matches.', 'Player 1 sprints a set distance (sideline to sideline or net to baseline) before every ball. Player 2 feeds the ball the moment Player 1 completes the sprint. Player 1 must hit quality shots despite being physically fatigued.', ARRAY['Player 1 sprints from the singles sideline to the opposite singles sideline — one full width of the court.','The moment Player 1 touches the opposite sideline, Player 2 feeds a ball.','Player 1 must use correct footwork (split step, first step, recovery) despite fatigue.','Repeat 10 times. Rest 90 seconds. Play 3 rounds.','Track: does footwork quality degrade across the 10 repetitions? By how much?']::text[], ARRAY['The split step must happen even when exhausted — it is the most important footwork element.','Shorten your stride under fatigue — compact steps are more controllable than big strides.','Breathe on contact — the exhale on contact releases tension built up during the sprint.','Focus on the footwork components you know: split, first step, plant, recover.','Players who maintain footwork under fatigue have trained this specifically — it doesn''t happen by accident.']::text[], ARRAY['Skipping the split step when tired — the most dangerous footwork compromise.','Taking the sprint easy — must genuinely fatigue to replicate third-set conditions.','Mental resignation — continuing to compete with proper footwork despite fatigue is a competitive skill.']::text[], ARRAY['Baseline sprint: net to baseline instead of sideline to sideline — different fatigue pattern.','Burpee before ball: Player 1 does 5 burpees before the feed — extreme fatigue simulation.','Track degradation: score footwork quality 1-5 on each rep — chart how it changes.']::text[], ARRAY['footwork','fatigue','third set','advanced','conditioning','competition']::text[], 'json', '{"p1":{"x":335,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":65,"y1":850,"x2":335,"y2":850}],"shots":[{"x1":200,"y1":490,"x2":335,"y2":840},{"x1":335,"y1":845,"x2":100,"y2":100}],"areas":[{"x":335,"y":850,"r":20}]}'::jsonb),
  ('FW-026', 'Return Footwork: Step Into the Box', 'Footwork', 'Return Footwork', 'footwork', 'intermediate', 10, 2, 'pairs', 'Train the return footwork specifically — the combination of positioning stance, weight transfer, and step into the ball that produces the best return contact. Many players return flat-footed or step away from the ball rather than into it. This drill isolates the footwork component of the return: starting with weight on the balls of the feet, loading on the split step, and driving forward into the ball on the return swing.', 'Train the return footwork specifically — the combination of positioning stance, weight transfer, and step into the ball that produces the best return contact. Many players return flat-footed or step away from the ball rather than into it. This drill isolates the footwork component of the return: starting with weight on the balls of the feet, loading on the split step, and driving forward into the ball on the return swing.', 'Player 2 serves medium-pace serves from both courts. Player 1 focuses exclusively on the footwork of the return: ready stance weight distribution, split step timing, and the step into the ball. No focus on where the return goes.', ARRAY['Player 1 positions in the return ready stance: weight forward, feet slightly wider than shoulders.','Player 2 serves a medium-pace serve from the deuce court.','Player 1 split steps, first step toward the ball, and steps into the return with the front foot.','The return swing follows the footwork — not the other way around.','After 10 returns from deuce, switch to ad. Focus on whether the step goes toward or away from the ball.']::text[], ARRAY['Weight on balls of feet before the serve — not the heels.','The split step loads the legs — the landing is the coiled spring position.','First step: directly toward the ball, not sideways then toward.','Step into the ball with the front foot on the return swing — don''t step away.','The forward step transfers weight through the return and adds pace automatically.']::text[], ARRAY['Stepping backward away from the ball — produces a defensive, weak return.','Flat feet in the ready position — cannot split step effectively.','Front foot stepping sideways instead of toward the ball — loses the weight transfer.']::text[], ARRAY['Footwork only: Player 1 performs the footwork without swinging — pure footwork training.','Step into slow serve: Player 2 serves slowly to give Player 1 more time to feel the step.','Film the step: check if the front foot is stepping toward or away from the ball on video.']::text[], ARRAY['footwork','return','step in','intermediate','weight transfer','technique']::text[], 'json', '{"p1":{"x":265,"y":60},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":265,"y2":60}],"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":265,"y1":65,"x2":110,"y2":820}],"areas":[{"x":265,"y":60,"r":20}]}'::jsonb),
  ('FW-027', 'Bosu Ball Footwork: Unstable Surface Balance', 'Footwork', 'Balance', 'footwork', 'advanced', 10, 2, 'pairs', 'Build proprioception, balance, and ankle stability through footwork training on an unstable surface. Tennis footwork demands exceptional balance because contact is often made while moving, off-balance, or on one foot. Training balance on an unstable surface like a Bosu ball or balance board strengthens the stabilizing muscles of the ankle, knee, and hip — reducing injury risk and improving on-court balance in extreme positions.', 'Build proprioception, balance, and ankle stability through footwork training on an unstable surface. Tennis footwork demands exceptional balance because contact is often made while moving, off-balance, or on one foot. Training balance on an unstable surface like a Bosu ball or balance board strengthens the stabilizing muscles of the ankle, knee, and hip — reducing injury risk and improving on-court balance in extreme positions.', 'Player 1 stands on a Bosu ball (dome side up) or a folded towel for an unstable surface. Player 2 feeds light balls to Player 1 — Player 1 must shadow-volley or shadow-groundstroke while maintaining balance on the unstable surface.', ARRAY['Player 1 stands on the dome of a Bosu ball — feet hip-width apart.','Player 2 slowly feeds or points in directions — Player 1 performs shadow swings on the Bosu ball.','Player 1 must maintain balance throughout every shadow swing.','Perform 15 forehand shadows and 15 backhand shadows. Rest 60 seconds. Repeat 3 rounds.','Progress to real ball feeding when balance is consistent.']::text[], ARRAY['Start with smaller shadow swings — full-power swings on an unstable surface require advanced balance.','Eyes fixed on a point at net level — focal point helps balance.','Ankle and core are the stabilizers — consciously engage both.','Progress from two feet to one foot — single-leg balance is the advanced version.','If balance is lost, step off — never fight a fall on an unstable surface.']::text[], ARRAY['Locking the knees — slightly bent knees are more stable than locked.','Looking down — takes the focal point away and kills balance.','Full-power swings before balance is established — causes falls.']::text[], ARRAY['Single-leg balance: Player 1 stands on one foot on the Bosu — then shadow swings.','Ball feeding on Bosu: Player 2 feeds real balls — Player 1 returns while balancing.','Bosu squat hold: Player 1 holds a squat position on the Bosu for 30 seconds — builds stability.']::text[], ARRAY['footwork','balance','Bosu ball','advanced','proprioception','stability']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":200,"y2":840}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FW-028', 'Running Forehand: Open Stance Sprint Contact', 'Footwork', 'Movement Pattern', 'footwork', 'advanced', 10, 2, 'pairs', 'Develop the running forehand — hitting a full forehand while sprinting at full speed without stopping. The running forehand is used when a wide ball requires a sprint to reach it and there is no time to stop and set up. The contact must happen while still moving. This requires a completely different footwork sequence than the standard forehand: the plant step is replaced by a continuous sprint through the contact point.', 'Develop the running forehand — hitting a full forehand while sprinting at full speed without stopping. The running forehand is used when a wide ball requires a sprint to reach it and there is no time to stop and set up. The contact must happen while still moving. This requires a completely different footwork sequence than the standard forehand: the plant step is replaced by a continuous sprint through the contact point.', 'Player 2 feeds very wide balls to Player 1''s forehand — designed to require a full sprint to reach. Player 1 must sprint to the ball and hit a running forehand without stopping, continuing the sprint through the contact.', ARRAY['Player 1 starts at center baseline.','Player 2 feeds a very wide ball to Player 1''s forehand — barely reachable.','Player 1 sprints to the ball and hits a running forehand — no stopping allowed.','Player 1 continues moving after contact — recovery sprint begins immediately.','Repeat 12 times. Focus on maintaining swing quality despite the running contact.']::text[], ARRAY['The plant foot is still the anchor — even while running, one foot plants for the swing.','The plant is a brief deceleration, not a full stop — the sprint continues through contact.','Keep the swing compact — a running forehand cannot use the same full backswing as a set forehand.','Aim cross-court from a running position — it''s the highest-percentage direction.','After contact, the running momentum should carry you toward center, not further wide.']::text[], ARRAY['Stopping before the running forehand — changes it from a running stroke to a set stroke.','Full backswing on a running forehand — no time for it, contact passes before swing is ready.','Running further wide after contact instead of recovering toward center.']::text[], ARRAY['Running backhand: same drill on the backhand side.','Running forehand recovery: after the running forehand, Player 2 hits to the opposite side.','Running forehand and charge: after the running forehand, Player 1 sprints to the net.']::text[], ARRAY['footwork','running forehand','advanced','sprint contact','wide ball']::text[], 'json', '{"p1":{"x":345,"y":840},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":345,"y2":840}],"shots":[{"x1":200,"y1":490,"x2":348,"y2":850},{"x1":342,"y1":838,"x2":95,"y2":100}],"areas":[{"x":95,"y":100,"r":25}]}'::jsonb),
  ('FW-029', 'Footwork Patterns for Doubles: Poach Movement', 'Footwork', 'Doubles Footwork', 'footwork', 'intermediate', 12, 2, 'pairs', 'Develop the poach movement pattern for doubles — the lateral movement toward the center of the net to intercept a cross-court ball. The poach is the most attacking net movement in doubles, but it requires specific footwork: a diagonal step toward the center and the net simultaneously, followed by an explosive intercept volley. This drill trains the poach footwork as a stand-alone movement before adding it to live doubles situations.', 'Develop the poach movement pattern for doubles — the lateral movement toward the center of the net to intercept a cross-court ball. The poach is the most attacking net movement in doubles, but it requires specific footwork: a diagonal step toward the center and the net simultaneously, followed by an explosive intercept volley. This drill trains the poach footwork as a stand-alone movement before adding it to live doubles situations.', 'Player 1 stands at the net in the deuce-side net position (as a doubles net player). Player 2 hits cross-court balls from the deuce baseline. Player 1 must poach — move diagonally across the net and intercept each cross-court ball.', ARRAY['Player 1 positions at the net on the deuce side — 4-5 feet from the net, near the center service line.','Player 2 hits cross-court balls from the deuce baseline.','Player 1 must poach: diagonal step forward and across, intercept the ball, volley to the open court.','After the poach, Player 1 returns to the starting position.','Repeat 15 times. Track: how many poaches result in a won point?']::text[], ARRAY['Poach trigger: commit before the ball is hit — read Player 2''s swing, not the ball''s flight.','Diagonal step: move forward and across simultaneously — not just sideways.','Don''t be afraid to miss the poach — hesitation is worse than an unsuccessful poach.','After the poach, keep moving — don''t stop in the center of the court.','Recover to your side after the poach — if Player 1 is on the right, they switch to the left.']::text[], ARRAY['Moving laterally only — should always have a forward component.','Committing too late — the ball is already past the interception zone.','Not recovering — player stays in the center and leaves both sides open.']::text[], ARRAY['Fake poach: Player 1 moves as if to poach then retreats — Player 2 changes direction.','Signal poach: Player 2 signals the poach with a finger signal behind the back.','Full doubles: add a baseline player partner — poach creates open court for partner.']::text[], ARRAY['footwork','poach','doubles','intermediate','net movement','lateral']::text[], 'json', '{"p1":{"x":140,"y":510},"p2":{"x":280,"y":60},"moves":[{"x1":200,"y1":510,"x2":140,"y2":510}],"shots":[{"x1":280,"y1":70,"x2":130,"y2":600},{"x1":135,"y1":505,"x2":300,"y2":820}],"areas":[{"x":300,"y":820,"r":25}]}'::jsonb),
  ('FW-030', 'Footwork Grand Finale: Full Court Multi-Ball Movement', 'Footwork', 'Court Coverage', 'footwork', 'advanced', 20, 2, 'pairs', 'Synthesize all footwork skills in a comprehensive multi-ball movement assessment that covers every court zone. This drill uses rapid-fire ball feeding to all areas of the court — baseline wide balls, short balls, net balls, and everything in between — forcing Player 1 to use every footwork pattern trained throughout this category: split step, shuffle, crossover, forward sprint, diagonal sprint, backpedal, and recovery. The quality of footwork across all patterns is the measure of success.', 'Synthesize all footwork skills in a comprehensive multi-ball movement assessment that covers every court zone. This drill uses rapid-fire ball feeding to all areas of the court — baseline wide balls, short balls, net balls, and everything in between — forcing Player 1 to use every footwork pattern trained throughout this category: split step, shuffle, crossover, forward sprint, diagonal sprint, backpedal, and recovery. The quality of footwork across all patterns is the measure of success.', 'Player 2 stands at the net with a large basket of balls. Player 2 feeds balls rapidly to random positions across the entire court. Player 1 must cover every ball using the appropriate footwork for each position and return to center after every shot.', ARRAY['Player 2 feeds balls rapidly from a full basket — one every 3-4 seconds — to random court positions.','Player 1 must use the correct footwork for each ball: crossover for wide, forward sprint for short, backpedal for lobs.','Player 1 must hit every ball and recover to center baseline after each one.','Continue until the basket is empty (20-25 balls). Rest 2 minutes. Repeat 3 rounds.','Track: how many balls does Player 1 reach in time? How many does Player 1 recover to center from? Aim for 90%+ on both.']::text[], ARRAY['Split step before every ball — even when exhausted, the split step must not be skipped.','Read the ball early — the first 10 feet of ball flight reveal the landing zone.','Match the footwork to the distance: shuffle for short moves, crossover for long ones.','Recovery to center is non-negotiable — every ball, without exception.','Breathe between shots — recovery breathing is as important as movement speed.']::text[], ARRAY['Defaulting to shuffling for all balls — incorrect footwork for wide and short balls.','Not recovering to center — stays wherever the last shot was hit.','Mental fatigue causing footwork shortcuts — the drill reveals where footwork degrades first.']::text[], ARRAY['Timed version: how many of 25 balls can Player 1 reach in time within one basket?','Footwork scoring: award 1 point for each ball reached with correct footwork, 0 for incorrect footwork.','Partner version: two players rotate — one recovers, one hits, creates social pressure.']::text[], ARRAY['footwork','multi-ball','court coverage','advanced','comprehensive','assessment']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":65,"y2":850},{"x1":65,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":335,"y2":850},{"x1":335,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":200,"y2":660},{"x1":200,"y1":660,"x2":200,"y2":850}],"shots":[{"x1":200,"y1":490,"x2":65,"y2":840},{"x1":200,"y1":490,"x2":335,"y2":840},{"x1":200,"y1":490,"x2":200,"y2":680},{"x1":200,"y1":490,"x2":200,"y2":840}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('GW-031', 'Forehand Recovery: Wide Ball to Center', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the recovery pattern after a wide forehand — sprint wide, hit, and sprint back to center before the next ball arrives. Recovery after a wide forehand is one of the most critical physical and tactical skills in tennis. Poor recovery leaves the entire center and down-the-line side exposed. This drill trains the habit of automatic, immediate recovery as part of the swing itself — not an afterthought.', 'Train the recovery pattern after a wide forehand — sprint wide, hit, and sprint back to center before the next ball arrives. Recovery after a wide forehand is one of the most critical physical and tactical skills in tennis. Poor recovery leaves the entire center and down-the-line side exposed. This drill trains the habit of automatic, immediate recovery as part of the swing itself — not an afterthought.', 'Player 2 feeds wide to Player 1''s forehand, then immediately hits a second ball to the center or backhand side. Player 1 must hit the wide forehand and recover in time to handle the second ball. The second ball comes quickly — Player 1 has no time to admire their wide shot.', ARRAY['Player 2 feeds wide to Player 1''s forehand corner — well past the singles sideline.','Player 1 runs at full sprint, hits the forehand, and immediately sprints back toward center.','Player 2 hits a second ball to the center or backhand — Player 1 must get there in time.','Play out each sequence as a 2-3 ball point after the second ball lands.','Repeat 15 sequences per set. Goal: reach the second ball in time at least 12 out of 15 times.']::text[], ARRAY['Your first step after the wide forehand must go back toward center — immediately, not after watching the ball land.','Push off your outside foot the instant you complete the swing — this is your launch pad.','Cross-step when recovering — it is significantly faster than shuffling sideways.','Hit the wide forehand with a slightly shortened backswing — saves time for the recovery.','Always expect the next ball to come early — never assume Player 2 will wait.']::text[], ARRAY['Watching the wide forehand land instead of recovering immediately — costs a full second of recovery time.','Shuffling back instead of cross-stepping — far too slow for match-pace recovery.','Not recovering all the way to center — stopping halfway leaves the center still exposed.']::text[], ARRAY['Three-ball sequence: wide forehand, then center ball, then wide backhand — continuous lateral movement.','Player 2 increases the pace of the second ball — Player 1 must recover even faster.','Fitness version: no rest between sequences — 6 consecutive sequences without stopping.']::text[], ARRAY['forehand','recovery','footwork','lateral','intermediate','match-simulation']::text[], 'json', '{"p1":{"x":340,"y":855},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":340,"y2":855},{"x1":340,"y1":848,"x2":200,"y2":848}],"shots":[{"x1":200,"y1":70,"x2":340,"y2":840},{"x1":340,"y1":845,"x2":100,"y2":110},{"x1":200,"y1":60,"x2":200,"y2":820}],"areas":[{"x":100,"y":110,"r":30}]}'::jsonb),
  ('GW-032', 'Forehand and Backhand Four-Corner Accuracy Challenge', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 15, 2, 'pairs', 'Develop precise directional control on both groundstrokes by targeting specific cones in all four corners of the court. Accuracy is a distinct skill from consistency — players can be consistent while missing their target by 5 feet on every shot. This drill trains the ability to consciously aim and place the ball, turning a vague sense of direction into a precise, repeatable skill.', 'Develop precise directional control on both groundstrokes by targeting specific cones in all four corners of the court. Accuracy is a distinct skill from consistency — players can be consistent while missing their target by 5 feet on every shot. This drill trains the ability to consciously aim and place the ball, turning a vague sense of direction into a precise, repeatable skill.', 'Place a cone 2 feet inside each of the 4 baseline corners of the court (deuce deep, ad deep on both sides). Player 2 feeds and calls a target corner before each ball. Player 1 must aim the groundstroke for the called corner.', ARRAY['Place a cone at each corner: deuce near, deuce far, ad near, ad far — all 2 feet inside the corner.','Player 2 feeds the ball and calls the target corner out loud before Player 1 hits.','Player 1 must aim their groundstroke for the called corner.','Score: +3 if within 1 foot of the cone, +2 if within 3 feet, +1 if on the correct half of the court.','Play 20 balls per set. Target: 35+ points out of a possible 60.']::text[], ARRAY['Decide the target early — before the ball reaches you, not while you are already swinging.','Change your aim completely based on the call — don''t default to your favorite corner.','Visualize the target vividly before you swing — mental clarity directly improves physical accuracy.','Decelerate slightly for precision shots — a 90% swing to the right spot beats 100% to the wrong one.','After each miss, analyze specifically: was it swing path or contact point that sent it off target?']::text[], ARRAY['Defaulting to favorite corners regardless of the call — defeats the entire randomization purpose.','Going for corners from an impossible position — learn when not to aim at the corner.','Making the decision after the swing has already started — always too late to redirect.']::text[], ARRAY['Add service line targets — 6 total cones for more variety.','Player 2 calls the target after Player 1 has already begun preparation — late-decision training.','Both players call targets for each other and play the full point out.']::text[], ARRAY['forehand','backhand','accuracy','target','intermediate','placement']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":200,"y2":820},{"x1":200,"y1":840,"x2":95,"y2":100},{"x1":200,"y1":840,"x2":300,"y2":100}],"cones":[{"x":95,"y":100},{"x":300,"y":100},{"x":95,"y":840},{"x":300,"y":840}]}'::jsonb),
  ('GW-033', 'Slice Drop-Slice Deep Pattern', 'Groundwork', 'Slice', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Develop the slice drop-slice deep combination — a subtle but devastating two-shot pattern where a deep slice pushes the opponent back, then an identical-looking slice becomes a drop shot. The contrast between deep and very short forces the opponent to cover maximum court distance. This only works with a perfect disguise — the drop shot preparation must be completely indistinguishable from the deep slice setup.', 'Develop the slice drop-slice deep combination — a subtle but devastating two-shot pattern where a deep slice pushes the opponent back, then an identical-looking slice becomes a drop shot. The contrast between deep and very short forces the opponent to cover maximum court distance. This only works with a perfect disguise — the drop shot preparation must be completely indistinguishable from the deep slice setup.', 'Player 1 rallies with slice from the baseline. After 2 deep slices to push Player 2 back, Player 1 attempts a disguised drop shot on the 3rd slice. Player 2 must try to reach every drop shot.', ARRAY['Player 1 and Player 2 begin a slice backhand rally.','Player 1 hits 2 deep slices to push Player 2 well behind the baseline.','On the 3rd slice, Player 1 hits a disguised drop shot that barely clears the net.','The setup, backswing, and early swing path for the drop shot must look identical to the deep slice.','Play out each point. Score: +2 if Player 2 cannot reach the drop shot, +1 if Player 2 reaches it but Player 1 wins.']::text[], ARRAY['The disguise lives in the follow-through only — not the backswing or backswing preparation.','Deep slice: full follow-through forward and through the ball.','Drop shot: decelerate through contact, open the face slightly, almost stop the swing.','Choose the drop shot only when Player 2 is pushed well behind the baseline — never when they''re neutral.','Best timing: hit it when Player 2 has taken a step backward from your last deep slice.']::text[], ARRAY['Different backswing for the drop shot — immediately telegraphed to Player 2.','Hitting the drop shot when Player 2 is inside the baseline — too easy to reach.','Drop shot not clearing the net — this is the most common technical error on slice drop shots.']::text[], ARRAY['Reverse pattern: drop shot first, deep slice second — catches players who move back after a drop.','Add a lob after the drop shot: Player 2 sprints to the drop, Player 1 lobs over them.','Doubles variation: drop shot to the doubles alley angle.']::text[], ARRAY['slice','drop shot','pattern','disguise','advanced','tactical']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":120,"y1":840,"x2":295,"y2":100},{"x1":295,"y1":70,"x2":110,"y2":820},{"x1":110,"y1":840,"x2":260,"y2":330}],"areas":[{"x":295,"y":110,"r":30},{"x":260,"y":330,"r":22}],"cones":[{"x":260,"y":330}]}'::jsonb),
  ('GW-034', 'Forehand Slow Rally Then Fast Finish', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the tempo shift — the ability to change gears deliberately from slow, patient baseline play to an explosive attacking shot. Many players can either rally consistently at a slow pace or hit hard, but they struggle to transition between both in the same point. The gear-shift — changing pace from building to finishing — is one of the most important tactical skills in modern tennis.', 'Train the tempo shift — the ability to change gears deliberately from slow, patient baseline play to an explosive attacking shot. Many players can either rally consistently at a slow pace or hit hard, but they struggle to transition between both in the same point. The gear-shift — changing pace from building to finishing — is one of the most important tactical skills in modern tennis.', 'Both players rally at slow-medium pace for a set number of shots, then on the 5th shot Player 1 accelerates to maximum pace. The contrast in pace is the entire weapon. Player 2 must handle the sudden acceleration.', ARRAY['Both players rally cross-court forehands at 40-50% pace for 4 shots.','On the 5th shot, Player 1 accelerates to 100% — rips the forehand with full commitment.','Play out the point after the acceleration.','After 5 rounds, increase the slow shots to 6 before the acceleration — makes the buildup longer.','The slow shots must look identical in setup to the acceleration shot — no telegraphing.']::text[], ARRAY['The slow shots are not weak shots — they are medium-quality balls that reset your opponent''s expectations.','On the acceleration shot: same setup, more leg drive, more hip rotation, more wrist snap.','Don''t telegraph with your body — the other player should feel the acceleration, not see it coming.','After the acceleration, be ready to continue — don''t assume it is an automatic winner.','The gear-shift only works when the slow shots are consistent enough to create a false rhythm.']::text[], ARRAY['Telegraphing the acceleration with a bigger backswing or wider stance — kills the surprise.','Slow shots landing short — makes the buildup obvious and gives the opponent an attack ball.','Acceleration going into the net — poor topspin on the change-of-pace shot.']::text[], ARRAY['Player 2 accelerates instead on any shot — Player 1 must read and defend without warning.','Both players can accelerate at any time — first player to hit a winner or force an error wins the point.','Add drop shot as a third gear: slow, fast, or drop — Player 1 picks any on any shot.']::text[], ARRAY['forehand','tempo','gear change','tactical','intermediate','pace']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":280,"y1":840,"x2":110,"y2":90},{"x1":110,"y1":70,"x2":275,"y2":840},{"x1":275,"y1":840,"x2":95,"y2":80}],"areas":[{"x":95,"y":100,"r":30}],"cones":[{"x":95,"y":80}]}'::jsonb),
  ('GW-035', 'Backhand Emergency: Full-Sprint Running Stroke', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Develop the emergency backhand — hitting a quality stroke while running at full speed with no time to set up. In match play, players are regularly forced to hit their backhand while sprinting, with zero time for proper preparation. This drill trains the running backhand technique: staying low, using body momentum as the power source, keeping the swing compact, and returning the ball with enough depth to reset the point.', 'Develop the emergency backhand — hitting a quality stroke while running at full speed with no time to set up. In match play, players are regularly forced to hit their backhand while sprinting, with zero time for proper preparation. This drill trains the running backhand technique: staying low, using body momentum as the power source, keeping the swing compact, and returning the ball with enough depth to reset the point.', 'Player 2 feeds hard balls wide to Player 1''s backhand side — well past the singles sideline, barely reachable. Player 1 must chase the ball at 100% sprint and hit a running backhand back into the court.', ARRAY['Player 1 starts at center baseline in the ready position.','Player 2 hits a hard ball wide to Player 1''s backhand — designed to be barely reachable at full sprint.','Player 1 sprints at maximum effort, reaches the ball, and hits a running backhand.','The goal is to get the ball back deep in the court — winning the point is secondary to good technique.','Repeat 10 times per set. Rest 90 seconds between sets. Play 3 sets.']::text[], ARRAY['Take a compact swing — there is no time for a full loop backswing at full sprint.','Use your body''s momentum to power the shot — lean into your direction of travel.','Stay low throughout — dropping your center of gravity helps with both sprint and contact.','Aim cross-court — it is the highest-percentage shot by far from a stretched position.','After the running backhand, immediately start moving toward your recovery position.']::text[], ARRAY['Slowing down before hitting — should maintain sprint speed all the way through contact.','Full loop backswing while running — wastes critical time, often results in a mis-hit.','Aiming down-the-line from a stretched position — far too risky from a compromised stance.']::text[], ARRAY['Add recovery: after the running backhand, Player 2 hits a normal ball — Player 1 must recover and play.','Competition: how many running backhands can Player 1 keep in court out of 10?','Both wings: alternate between wide forehand sprint and wide backhand sprint.']::text[], ARRAY['backhand','running','emergency','defensive','advanced','pressure']::text[], 'json', '{"p1":{"x":50,"y":820},"p2":{"x":280,"y":60},"moves":[{"x1":200,"y1":850,"x2":50,"y2":820}],"shots":[{"x1":280,"y1":70,"x2":50,"y2":790},{"x1":50,"y1":810,"x2":295,"y2":110}],"areas":[{"x":295,"y":120,"r":35}]}'::jsonb),
  ('GW-036', 'Forehand Finishing: Short Ball Attack', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the ability to recognize and finish points with the forehand on a short ball opportunity. Recognizing a short ball early and executing an aggressive attacking forehand is a skill that separates competitive players from recreational ones. Players who miss short ball opportunities give their opponent time to recover and often lose points they should have won. This drill trains recognition, approach, and the aggressive attacking swing.', 'Train the ability to recognize and finish points with the forehand on a short ball opportunity. Recognizing a short ball early and executing an aggressive attacking forehand is a skill that separates competitive players from recreational ones. Players who miss short ball opportunities give their opponent time to recover and often lose points they should have won. This drill trains recognition, approach, and the aggressive attacking swing.', 'Player 2 drops a short ball (landing between the net and service line) to Player 1''s forehand side. Player 1 must recognize the short ball immediately and sprint forward to finish the point.', ARRAY['Player 2 drops a short ball onto Player 1''s forehand side — landing short of the service line.','Player 1 must sprint forward immediately and hit an aggressive attacking forehand.','The shot should be a winner, an approach to net, or at minimum a very deep forcing shot.','Play out each point: if Player 1 does not win outright, the rally continues.','Repeat 15 times. Track percentage of short balls converted into winners or points won.']::text[], ARRAY['Read the short ball early — call out ''short ball!'' in your head the moment it clears the net.','Sprint in, don''t jog — the window to attack a short ball is very small.','Step into the ball — your momentum should be moving forward through the entire contact.','Hit up through the ball with topspin — short balls need spin to stay in the court.','After the attack, either follow to the net or recover depending on the quality of the shot.']::text[], ARRAY['Hesitating on the recognition — by the time the player attacks, the ball has bounced twice.','Jogging to the short ball instead of sprinting — arrives late and cannot generate pace.','Hitting flat into the net on a low ball — topspin is essential on short balls.']::text[], ARRAY['Add a rally before the short ball: 3 neutral baseline shots, then Player 2 drops a short ball.','Player 2 varies the short ball position: forehand corner, center, backhand corner.','Scoring system: +2 for outright winner, +1 for putting the point away within 3 shots.']::text[], ARRAY['forehand','short ball','attack','finishing','intermediate','offensive']::text[], 'json', '{"p1":{"x":280,"y":660},"p2":{"x":120,"y":60},"moves":[{"x1":280,"y1":860,"x2":280,"y2":660}],"shots":[{"x1":120,"y1":70,"x2":275,"y2":630},{"x1":275,"y1":650,"x2":95,"y2":100}],"areas":[{"x":95,"y":110,"r":28}],"cones":[{"x":95,"y":110}]}'::jsonb),
  ('GW-037', 'Backhand DTL vs CC Guess Game', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Develop the backhand DTL as a genuine match weapon by incorporating a competitive guessing game that demands real disguise. Player 2 must guess the direction before Player 1 hits. The competitive element teaches Player 1 to conceal the direction and teaches Player 2 to read early cues — both skills transferring directly and immediately into match play.', 'Develop the backhand DTL as a genuine match weapon by incorporating a competitive guessing game that demands real disguise. Player 2 must guess the direction before Player 1 hits. The competitive element teaches Player 1 to conceal the direction and teaches Player 2 to read early cues — both skills transferring directly and immediately into match play.', 'Player 2 feeds to Player 1''s backhand. Before Player 1 hits, Player 2 calls either ''DTL'' or ''CC''. Player 1 scores a point by successfully going the opposite direction. Player 2 scores a point by guessing correctly.', ARRAY['Player 2 feeds a medium ball to Player 1''s backhand.','Player 2 calls ''DTL'' or ''CC'' before Player 1''s swing begins.','Player 1 tries to go the opposite direction — disguise wins points.','If Player 2 guesses correctly: +1 for Player 2.','If Player 2 guesses wrong: +1 for Player 1. First to 10 wins. Switch roles.']::text[], ARRAY['The game reveals your specific tells — if Player 2 always guesses correctly, you are telegraphing something.','Identical setup for both directions — let the contact point difference reveal the direction, not your body.','Mix in patterns deliberately: 3 CC then DTL — create a false pattern then break it.','If Player 2 always guesses DTL, just go CC every time — exploit predictable guessing.','Randomize genuinely — conscious randomization prevents predictable shot patterns.']::text[], ARRAY['Going DTL from a defensive or stretched position — poor tactical choice regardless of the drill.','Player 2 always guessing the same direction — not actually reading, just gambling.','Predictable sequences like CC, CC, DTL, CC, CC, DTL — Player 2 reads the pattern easily.']::text[], ARRAY['Add a third option: Player 1 can also go ''middle'' — now Player 2 must guess between three directions.','Both players rally and play out the full point after the first backhand.','Bonus points: +2 if Player 1 wins the full point outright, regardless of the guessing result.']::text[], ARRAY['backhand','DTL','disguise','game','advanced','match-simulation']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":280,"y1":70,"x2":110,"y2":820},{"x1":110,"y1":840,"x2":295,"y2":100},{"x1":110,"y1":840,"x2":90,"y2":100}],"areas":[{"x":295,"y":100,"r":25},{"x":90,"y":100,"r":25}]}'::jsonb),
  ('GW-038', 'Forehand Windshield Wiper Finish Isolation', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Isolate and train the windshield wiper follow-through — the defining feature of the modern heavy topspin forehand. After contact, the racket sweeps from low-right to high-left (for right-handers), like a windshield wiper across the face of the ball. This motion dramatically increases topspin by brushing across the back of the ball, snapping the wrist through, and allowing the ball to stay on the strings longer. It is the foundation of the modern forehand.', 'Isolate and train the windshield wiper follow-through — the defining feature of the modern heavy topspin forehand. After contact, the racket sweeps from low-right to high-left (for right-handers), like a windshield wiper across the face of the ball. This motion dramatically increases topspin by brushing across the back of the ball, snapping the wrist through, and allowing the ball to stay on the strings longer. It is the foundation of the modern forehand.', 'Player 2 feeds slow, comfortable balls to Player 1''s forehand. Player 1 focuses entirely on the windshield wiper follow-through on every ball — consciously exaggerating the motion to groove it.', ARRAY['Player 2 feeds slow, comfortable balls to Player 1''s forehand.','Player 1 hits every forehand with a deliberate, exaggerated windshield wiper follow-through.','After contact, the racket should sweep left (for right-handers), finishing pointing left — not up over the shoulder.','Player 1 exaggerates the finish for the first 10 balls — over-correcting to find the motion clearly.','For the next 10 balls, scale back to a natural swing — the habit should be forming.']::text[], ARRAY['After contact, the wrist rolls from low-right to high-left — a sweeping motion across the ball.','Think ''wiper'' — the racket face sweeps across the back of the ball, not straight through it.','The wiper motion comes from forearm rotation combined with wrist snap — not wrist alone.','You should feel the ball stay on the strings slightly longer — that extra time creates more topspin.','Finish with the racket face pointing left — not upward, not over the shoulder.']::text[], ARRAY['Finishing over the shoulder without the wiper sweep — old-school finish, far less topspin.','Wrist snap only without forearm rotation — weak and inconsistent, misses the full motion.','Starting the wiper motion before contact — ruins the contact point and direction control.']::text[], ARRAY['Slow-motion practice: take the swing entirely in slow motion, pausing at the finish position.','Film the finish: use a phone in slow motion to check the racket face orientation at completion.','Target topspin: place a target on the far side — the wiper topspin should kick it well above shoulder height.']::text[], ARRAY['forehand','windshield wiper','topspin','technique','intermediate']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":280,"y2":820},{"x1":280,"y1":840,"x2":110,"y2":100}],"areas":[{"x":110,"y":110,"r":30}]}'::jsonb),
  ('GW-039', 'Backhand Chip and Charge', 'Groundwork', 'Slice', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Develop the chip-and-charge — one of the most aggressive and effective tactical patterns available in tennis. On a weak second serve, a short ball, or a slow floated return, the player chips a compact slice backhand and immediately follows it to the net. The slice stays low and skidding, making it difficult to drive a passing shot, while the rush to the net immediately puts enormous pressure on the opponent.', 'Develop the chip-and-charge — one of the most aggressive and effective tactical patterns available in tennis. On a weak second serve, a short ball, or a slow floated return, the player chips a compact slice backhand and immediately follows it to the net. The slice stays low and skidding, making it difficult to drive a passing shot, while the rush to the net immediately puts enormous pressure on the opponent.', 'Player 2 serves (or feeds from the service line) a medium-paced ball to Player 1''s backhand. Player 1 chips a slice return and sprints immediately and aggressively to the net.', ARRAY['Player 2 feeds or serves a medium-paced ball to Player 1''s backhand.','Player 1 chips a compact slice backhand — directing it down the middle or DTL.','Player 1 immediately sprints to the net without hesitation, reaching the T or close to it.','Player 2 attempts a passing shot — Player 1 volleys the finish.','Play each sequence as a full point. Repeat 15 times.']::text[], ARRAY['The chip must be compact and decisive — this is not the time for a large, elaborate backswing.','Direct the chip down the middle or DTL — cross-court gives the opponent a wider passing angle.','Move through the shot — don''t stop your feet to watch the chip land.','Split step as Player 2 prepares to pass — before their racket contacts the ball.','Volley finish with a short, punchy motion — stay compact and don''t overswing at the net.']::text[], ARRAY['Chip going short and floating — gives the opponent an easy high ball to drive a pass.','Stopping after the chip to watch it land — arrives at the net far too late.','No split step before the volley — reactive volley is always late.']::text[], ARRAY['Chip and charge from the deuce side using a forehand chip.','Add a second volley: Player 2 hits a tough pass, Player 1 hits a first volley and a finishing volley.','Doubles version: serve wide plus chip-and-charge, with partner at net intercepting.']::text[], ARRAY['slice','chip','approach','net play','intermediate','aggressive']::text[], 'json', '{"p1":{"x":120,"y":715},"p2":{"x":280,"y":60},"moves":[{"x1":120,"y1":860,"x2":120,"y2":715},{"x1":120,"y1":705,"x2":155,"y2":510}],"shots":[{"x1":280,"y1":70,"x2":110,"y2":685},{"x1":110,"y1":705,"x2":200,"y2":100},{"x1":280,"y1":120,"x2":163,"y2":500}],"areas":[{"x":200,"y":100,"r":30}]}'::jsonb),
  ('GW-040', 'Forehand Serve Plus One Inside-Out Pattern', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Develop the serve-plus-one forehand pattern — the single most common point-winning combination in modern professional tennis. Player serves wide or to the T, reads the return, then runs around the backhand to hit an inside-out forehand into the open court. The serve creates the opening; the inside-out forehand exploits it. This pattern is the tactical backbone of countless professional players'' games.', 'Develop the serve-plus-one forehand pattern — the single most common point-winning combination in modern professional tennis. Player serves wide or to the T, reads the return, then runs around the backhand to hit an inside-out forehand into the open court. The serve creates the opening; the inside-out forehand exploits it. This pattern is the tactical backbone of countless professional players'' games.', 'Player 1 serves from the deuce court. Player 2 returns. If the return comes to the backhand area, Player 1 must run around it and hit an inside-out forehand on the very next ball.', ARRAY['Player 1 serves wide to the deuce court — pulling Player 2 wide.','Player 2 returns — if the return goes near the backhand, Player 1 runs around it.','Player 1 hits an inside-out forehand on the plus-one ball to the open ad-side corner.','Play out the point after the plus-one forehand.','Repeat 12 times. Track: how many plus-one forehands land in the target zone?']::text[], ARRAY['Start moving toward the center the moment the serve leaves your racket — anticipate the return.','A wide deuce court serve creates a likely cross-court return — start reading early.','The inside-out forehand goes to the ad side — the open court created by the wide serve.','Be aggressive on the plus-one — this is your designed tactical opportunity.','If the return goes to your forehand already, adjust to an inside-in forehand instead.']::text[], ARRAY['Not moving after the serve — waiting to see where the return lands before deciding.','Serve too slow — return is too aggressive and arrives before Player 1 is in position.','Inside-out forehand going DTL accidentally — opens your own cross-court instead of the opponent''s.']::text[], ARRAY['T serve plus forehand: serve to the T, anticipate the CC return, run around for inside-out.','Ad court version: serve wide, run around backhand, inside-out forehand.','Three-ball pattern: serve, inside-out, then finishing forehand — adds a third shot.']::text[], ARRAY['forehand','serve+1','pattern','inside-out','intermediate','tactical']::text[], 'json', '{"p1":{"x":130,"y":840},"p2":{"x":100,"y":60},"moves":[{"x1":240,"y1":855,"x2":130,"y2":840}],"shots":[{"x1":240,"y1":855,"x2":80,"y2":365},{"x1":100,"y1":70,"x2":195,"y2":785},{"x1":130,"y1":840,"x2":90,"y2":100}],"areas":[{"x":90,"y":100,"r":30}]}'::jsonb),
  ('GW-041', 'Forehand Contact Point Variation: Early, Standard, Late', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Train the ability to deliberately hit the forehand with three distinct contact points — early (in front of the body for DTL), standard (neutral for cross-court), and late (further back for inside-out DTL or angle). Most players hit every forehand at the same contact point by default. Elite players consciously vary the contact point to create different shot shapes, angles, and directions from the same position.', 'Train the ability to deliberately hit the forehand with three distinct contact points — early (in front of the body for DTL), standard (neutral for cross-court), and late (further back for inside-out DTL or angle). Most players hit every forehand at the same contact point by default. Elite players consciously vary the contact point to create different shot shapes, angles, and directions from the same position.', 'Player 2 feeds steady medium-paced balls to Player 1''s forehand. Player 1 cycles through three contact points: early, standard, late — changing direction accordingly with each.', ARRAY['Player 2 feeds medium-paced balls consistently to Player 1''s forehand.','Shot 1: early contact (very in front of the body) — ball goes down-the-line or creates a sharp angle.','Shot 2: standard contact (front of the hip) — ball goes cross-court.','Shot 3: late contact (further back, past the hip) — ball goes inside-out DTL.','Cycle through all 3 contact points in sequence for 15 cycles.']::text[], ARRAY['Early contact: step across early and take the ball well in front — aggressive, moves the ball DTL.','Standard: contact at the ideal front-hip point — most consistent, naturally goes CC.','Late contact: let the ball travel past the hip — unusual feel, creates inside-out or sharp angle.','Your feet control the contact point — never try to adjust the contact point with your arm.','The arm position at contact is identical for all three — only the timing and foot position change.']::text[], ARRAY['Adjusting the contact point with the arm instead of feet — creates inconsistency.','Excessively late contact — ball drifts to the back fence.','Not actually changing the landing direction when changing contact point — missing the purpose.']::text[], ARRAY['Random: Player 2 calls ''early'', ''standard'', or ''late'' before each feed — real-time adaptation.','Build to match play: after 3 contact point practice shots, play out the point freely.','Two-shot sequence: early-contact DTL then standard-contact CC — the classic redirect pattern.']::text[], ARRAY['forehand','contact point','advanced','technique','direction','tactical']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":70,"x2":280,"y2":840},{"x1":280,"y1":840,"x2":90,"y2":100},{"x1":280,"y1":840,"x2":110,"y2":90},{"x1":280,"y1":840,"x2":295,"y2":110}],"areas":[{"x":90,"y":100,"r":22},{"x":110,"y":90,"r":22},{"x":295,"y":110,"r":22}]}'::jsonb),
  ('GW-042', 'No-Doubles-Alley Baseline Rally', 'Groundwork', 'Forehand', 'groundstrokes', 'beginner', 10, 2, 'pairs', 'Build directional control and singles court awareness by adding a zone restriction — no balls may land in the doubles alleys. This forces players to consciously aim within the singles court on every shot and develops real awareness of where the singles sidelines are from every position on the court. Most beginners go wide far more than they realize — this drill makes that immediately visible and corrects it.', 'Build directional control and singles court awareness by adding a zone restriction — no balls may land in the doubles alleys. This forces players to consciously aim within the singles court on every shot and develops real awareness of where the singles sidelines are from every position on the court. Most beginners go wide far more than they realize — this drill makes that immediately visible and corrects it.', 'Both players rally from the baseline using any groundstroke and any direction. Any ball landing outside the singles sidelines (in the doubles alley) is an automatic error and loses the count. Play singles court only.', ARRAY['Begin a baseline rally — any groundstroke, any direction within the singles court.','Any ball landing in the doubles alley is an immediate error — call it out.','Count how many consecutive shots both players keep inside the singles court.','Target: 20 consecutive shots without hitting the doubles alley.','If 20 is easy, progress to 30 or add a depth restriction.']::text[], ARRAY['Aim 2-3 feet inside the singles sideline on every shot — always give yourself a real margin.','Wide balls often go to the alley when the player is rushed — use this drill to identify when that happens.','After a near-miss wide shot, consciously tighten your aim on the very next ball.','Notice if you consistently miss wide to the same side — that reveals a technical or tactical pattern.','The singles sideline is your friend — respect it and you will make far fewer unforced errors.']::text[], ARRAY['Aiming right at the line — any slight mis-hit goes wide into the alley.','Fatigue causing sloppy aim in long rallies — this drill reveals when technique degrades.','Not knowing where the singles sideline is from each different position on the court.']::text[], ARRAY['Play full points: first player to hit the alley loses the point outright.','Relax the rule: one alley miss per 10-shot rally is allowed — teaches risk management.','Combine restrictions: no doubles alley AND must land past the service line — singles width AND depth.']::text[], ARRAY['forehand','backhand','accuracy','court awareness','beginner','consistency']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":280,"y2":90},{"x1":200,"y1":70,"x2":120,"y2":830}],"areas":[{"x":200,"y":80,"r":60},{"x":200,"y":840,"r":60}]}'::jsonb),
  ('GW-043', 'Slice Rally: Adapting to Varied Incoming Spins', 'Groundwork', 'Slice', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Build slice consistency when the incoming ball carries different spins — topspin, flat, and slice. Each incoming spin requires a different adjustment: a topspin ball bounces high and comes steeply, a flat ball moves low and fast, and an incoming slice stays low and skids. This drill forces players to adapt their slice technique to all three scenarios, which is exactly what happens in matches.', 'Build slice consistency when the incoming ball carries different spins — topspin, flat, and slice. Each incoming spin requires a different adjustment: a topspin ball bounces high and comes steeply, a flat ball moves low and fast, and an incoming slice stays low and skids. This drill forces players to adapt their slice technique to all three scenarios, which is exactly what happens in matches.', 'Player 2 alternates the spin of each feed in sequence: topspin, flat, slice. Player 1 must return every single ball with a slice backhand, adjusting technique for each incoming spin type.', ARRAY['Player 2 hits a topspin ball — Player 1 adjusts to the high bounce and slices.','Player 2 hits a flat ball — Player 1 adjusts to the flat, fast trajectory and slices.','Player 2 hits a slice — Player 1 manages the low skidding ball and slices.','Repeat in this sequence for 15 cycles.','After the structured sequence, Player 2 mixes randomly — Player 1 must identify and react immediately.']::text[], ARRAY['Against topspin: take the ball early before it kicks too high, or drop very low and slice upward.','Against flat: the ball comes fast and low — use a compact, direct slice to control direction.','Against slice: it stays very low and skids — get your racket below the ball early.','Read the opponent''s racket angle at contact to anticipate the incoming spin before the ball crosses the net.','The slice fundamentals stay the same — only the setup point and racket position at contact change.']::text[], ARRAY['Using the same slice technique for all three incoming spins — at least one will always be wrong.','Not reading spin early enough — preparing too late for the topspin or flat ball.','Floating the slice against a topspin ball — taking it too high, net error.']::text[], ARRAY['All-topspin set: Player 2 hits only heavy topspin — Player 1 slices every one.','Pure slice duel: both players slice every ball — who keeps it lowest and deepest?','Live points: Player 1 must slice every ball regardless of spin; Player 2 uses any stroke.']::text[], ARRAY['slice','consistency','spin recognition','intermediate','adaptive']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":280,"y1":70,"x2":110,"y2":810},{"x1":110,"y1":840,"x2":295,"y2":100},{"x1":295,"y1":70,"x2":115,"y2":820},{"x1":115,"y1":840,"x2":290,"y2":100}],"areas":[{"x":290,"y":110,"r":30},{"x":115,"y":820,"r":30}]}'::jsonb),
  ('GW-044', 'Backhand Topspin vs Slice Decision Under Pressure', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Train the real-time split-second decision between topspin and slice on the backhand — a choice that must happen in a fraction of a second based on ball height, court position, and tactical state. Making this decision automatically — not consciously thinking it through — is the hallmark of an advanced player. This drill forces the decision under varied, unpredictable conditions.', 'Train the real-time split-second decision between topspin and slice on the backhand — a choice that must happen in a fraction of a second based on ball height, court position, and tactical state. Making this decision automatically — not consciously thinking it through — is the hallmark of an advanced player. This drill forces the decision under varied, unpredictable conditions.', 'Player 2 feeds balls randomly varying in height, width, and depth without signaling which type is coming. Player 1 must read the ball and decide topspin or slice instantly and execute the correct shot.', ARRAY['Player 2 feeds balls varying in height, depth, and width without signaling the type.','Player 1 must read the ball and choose: topspin or slice — and commit immediately.','General guide: topspin on balls at waist height or below from a neutral position. Slice on balls above shoulder or when stretched wide.','After 20 balls, Player 2 reveals which decisions were ideal and why — discuss and learn.','Repeat 2 more sets applying the feedback.']::text[], ARRAY['Key trigger: if you are comfortable and balanced — topspin. If stretched or defensive — slice.','High bouncing ball at shoulder: topspin if below shoulder, slice if above.','Wide ball: almost always slice — the stretch makes topspin technically difficult.','After a defensive slice, look for the next ball to hit topspin — rebuild the offensive.','Make the decision before the ball crosses the net — never at the last second.']::text[], ARRAY['Defaulting to one stroke regardless of the tactical situation — takes thinking out but also takes out effectiveness.','Topspin on balls that are too high — forced, awkward, cramped swing.','Slice when topspin would have been more effective — overly cautious, gives up the offense.']::text[], ARRAY['Add the forehand to the mix: Player 2 can feed to either wing — Player 1 must choose wing and spin.','Live points: Player 1 can use any backhand spin freely in real-time during a point.','Scoring: +1 for correct spin choice regardless of outcome, +2 if the shot lands in the target zone.']::text[], ARRAY['backhand','topspin','slice','decision','advanced','match-simulation']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":110,"y2":810},{"x1":110,"y1":840,"x2":295,"y2":100},{"x1":200,"y1":490,"x2":55,"y2":820},{"x1":55,"y1":820,"x2":290,"y2":110}],"areas":[{"x":295,"y":100,"r":28},{"x":290,"y":110,"r":28}]}'::jsonb),
  ('GW-045', 'Forehand Cross-Court: Progressively Tighter Target', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Develop laser-precise accuracy on the cross-court forehand by progressively shrinking the target zone as the player succeeds. Starting with a large, forgiving target and systematically reducing it builds focus intensity, sharpens the aim mechanism, and creates the precision needed under real match pressure when every inch matters against a good opponent.', 'Develop laser-precise accuracy on the cross-court forehand by progressively shrinking the target zone as the player succeeds. Starting with a large, forgiving target and systematically reducing it builds focus intensity, sharpens the aim mechanism, and creates the precision needed under real match pressure when every inch matters against a good opponent.', 'Place a cone in the forehand cross-court corner. Start with a large target zone (5-foot radius around the cone). Every 5 consecutive successful hits inside the zone, reduce the target radius by 1 foot. Continue until Player 1 can consistently hit within 1 foot of the cone.', ARRAY['Set the initial target zone: 5-foot radius from the corner cone.','Player 2 feeds steady balls to Player 1''s forehand.','Player 1 must land every forehand inside the current target zone.','After 5 consecutive successful shots, reduce the zone by 1 foot.','Continue reducing until Player 1 can hit within 1 foot of the cone consistently.']::text[], ARRAY['Visualize the target zone clearly before each shot — see it vividly, then commit to it.','As the target shrinks, reduce pace slightly — precision wins over power at small targets.','Your swing path dictates direction: fine-tune the path angle, not the wrist snap.','Stand still and breathe before each shot — tension physically widens your effective shot spread.','Note the relationship between your racket face angle and the landing spot after each shot.']::text[], ARRAY['Maintaining full pace as the target shrinks — forces errors and defeats the purpose.','Over-thinking the mechanics instead of feeling the swing — visualization beats analysis.','Not visualizing the target before each swing — random aim at a small target never works.']::text[], ARRAY['Time pressure: 30 seconds to get 5 consecutive hits in the smallest zone — adds mental pressure.','Move the cone to different targets: DTL corner, center baseline, wide angle.','Add recovery movement between each shot — simulates hitting precise targets after movement.']::text[], ARRAY['forehand','precision','target','progressive','intermediate','cross-court']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":70,"x2":280,"y2":830},{"x1":280,"y1":840,"x2":95,"y2":100}],"areas":[{"x":95,"y":100,"r":35},{"x":95,"y":100,"r":18}],"cones":[{"x":95,"y":100}]}'::jsonb),
  ('GW-046', 'Backhand Solo Wall Rally', 'Groundwork', 'Backhand', 'groundstrokes', 'beginner', 10, 1, 'individual', 'Build backhand consistency, rhythm, and contact point reliability using a practice wall. The wall is the ideal solo training partner — it feeds balls at a completely consistent pace, never misses, allows unlimited repetitions, and forces the player to maintain constant readiness. It is the fastest known method for grooving a reliable backhand through sheer repetition.', 'Build backhand consistency, rhythm, and contact point reliability using a practice wall. The wall is the ideal solo training partner — it feeds balls at a completely consistent pace, never misses, allows unlimited repetitions, and forces the player to maintain constant readiness. It is the fastest known method for grooving a reliable backhand through sheer repetition.', 'Player 1 stands 8-10 feet from a wall. Mark a target on the wall at net height (approximately 3.5 feet high). Player 1 rallies the backhand continuously against the wall target, trying to maintain a continuous, rhythmic rally.', ARRAY['Start 8 feet from the wall. Rally the backhand continuously against the target on the wall.','Count consecutive hits without a miss or break in rhythm.','Target: 50 consecutive backhand wall rallies without interruption.','After reaching 50, step back to 12 feet — the shorter time window challenges reaction speed.','Do 3 sets of 3 minutes each.']::text[], ARRAY['Use a full swing — don''t block or poke the ball at the wall.','Recover your racket back to the ready position immediately after each swing.','The wall reveals your contact point: if you are late, the ball goes high or wild.','Breathe with each swing — exhale on every contact.','Watch the ball off the wall, not the wall itself — track the ball in flight.']::text[], ARRAY['Standing too close to the wall — no time to swing properly, forces a jab.','Blocking the ball instead of swinging — should be a full stroke on every ball.','Not recovering the racket between swings — leads to poking the next ball.']::text[], ARRAY['Alternate forehand and backhand off the wall — switch grips on every single shot.','Use two targets marked left and right on the wall — alternate between them for directional control.','Slice on the wall: the ball stays lower and comes back faster — great for slice refinement.']::text[], ARRAY['backhand','wall','solo','consistency','beginner','rhythm']::text[], 'json', '{"p1":{"x":200,"y":750},"shots":[{"x1":200,"y1":740,"x2":200,"y2":480},{"x1":200,"y1":470,"x2":200,"y2":730}],"areas":[{"x":200,"y":480,"r":30}],"cones":[{"x":200,"y":480}]}'::jsonb),
  ('GW-047', 'Forehand Moonball to Attack Pattern', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Train the moonball-to-attack sequence — one of the most effective tactical combinations in baseline tennis. Player 1 hits 2-3 moonballs to push Player 2 deep behind the baseline, then attacks aggressively when Player 2 is forced to hit from a defensive position. The moonball is the setup; the attack is the finish. This teaches players to use patience strategically, not just defensively.', 'Train the moonball-to-attack sequence — one of the most effective tactical combinations in baseline tennis. Player 1 hits 2-3 moonballs to push Player 2 deep behind the baseline, then attacks aggressively when Player 2 is forced to hit from a defensive position. The moonball is the setup; the attack is the finish. This teaches players to use patience strategically, not just defensively.', 'Player 1 intentionally hits 2-3 moonballs to push Player 2 back behind the baseline. When Player 2''s reply comes short or weak, Player 1 transitions to an aggressive attack shot.', ARRAY['Player 1 hits 2-3 consecutive moonballs to Player 2 — high, heavy, deep.','Player 2, pushed back by the moonballs, returns from behind the baseline.','If Player 2''s return lands short (inside the service line), Player 1 attacks aggressively.','If Player 2''s return is deep, Player 1 hits one more moonball before looking to attack.','Play out each point. Track: how many moonball setups result in a short ball attack?']::text[], ARRAY['The moonball is not passive — it is active point-building with a purpose.','Watch Player 2''s position after each moonball — are they moving further back?','The attack comes on the short ball, not the deep ball — be disciplined about when to attack.','Transition from moonball to attack with a completely different swing path — commit to the change.','The contrast between slow moonball and fast attack is the entire weapon.']::text[], ARRAY['Attacking while Player 2 is still inside the baseline — wrong time, too much risk.','Moonballs landing short — gives Player 2 an attack ball instead of pushing them back.','Not recognizing the short ball opportunity — continuing to moonball when attack is available.']::text[], ARRAY['Player 2 tries to intercept and attack the moonball — Player 1 must adjust.','Add a drop shot option: after 2 moonballs, Player 1 can drop shot or attack.','Full match points: Player 1 must use at least 1 moonball in every point.']::text[], ARRAY['forehand','moonball','pattern','attack','tactical','intermediate']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":120,"y2":110},{"x1":120,"y1":70,"x2":200,"y2":820},{"x1":200,"y1":820,"x2":300,"y2":680}],"areas":[{"x":120,"y":110,"r":35},{"x":300,"y":680,"r":25}],"cones":[{"x":300,"y":680}]}'::jsonb),
  ('GW-048', 'Backhand Under Physical Load: Post-Sprint Stroke', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 15, 2, 'pairs', 'Train the backhand under genuine physical fatigue — the most demanding match condition of all. Players sprint a set distance before every single backhand, simulating the cardiovascular state of a long, hard baseline rally. The goal is to maintain technique, direction, and depth even when out of breath — the exact condition where most players'' backhands completely break down in tight matches.', 'Train the backhand under genuine physical fatigue — the most demanding match condition of all. Players sprint a set distance before every single backhand, simulating the cardiovascular state of a long, hard baseline rally. The goal is to maintain technique, direction, and depth even when out of breath — the exact condition where most players'' backhands completely break down in tight matches.', 'Player 1 sprints from the net to the baseline before each ball. Player 2 feeds to the backhand the instant Player 1''s foot touches the baseline. There is no recovery time between sprint and stroke.', ARRAY['Player 1 starts at the net in the ready position.','Player 1 sprints to the baseline at full speed.','As soon as Player 1 touches the baseline, Player 2 feeds to the backhand.','Player 1 must hit a quality cross-court backhand despite being out of breath.','Walk back to the net, then sprint again. Repeat 10 times per round. Rest 2 minutes. Play 3 rounds.']::text[], ARRAY['Control your breathing — exhale forcefully on contact.','Even when completely fatigued, complete the unit turn — incomplete turn is the first thing to go.','Shorten your swing slightly when very fatigued — compact but still controlled.','Take a full, slow breath during the walk back to the net — prepare for the next sprint.','Your technique will degrade under fatigue — train it until the degradation is minimal.']::text[], ARRAY['Swinging arm-only when fatigued — the legs are always the first thing to drop out.','Holding breath through contact — always exhale, never hold.','Slow footwork arriving at the ball — tired legs cause late positioning.']::text[], ARRAY['Add a target: Player 1 must hit 6 out of 10 into the target zone to pass the round.','Alternate wings: sprint, backhand, sprint, forehand — full-body fatigue.','Match simulation: play out each point after the sprint-feed backhand.']::text[], ARRAY['backhand','fatigue','fitness','advanced','match-simulation','pressure']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"moves":[{"x1":155,"y1":480,"x2":120,"y2":850}],"shots":[{"x1":280,"y1":70,"x2":110,"y2":800},{"x1":110,"y1":840,"x2":295,"y2":100}],"areas":[{"x":295,"y":110,"r":30}]}'::jsonb),
  ('GW-049', 'Groundwork Grand Finale: Free Rally with Shot Tracking', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 15, 2, 'pairs', 'Synthesize all groundwork skills in a free-rally format while tracking specific metrics. This assessment drill reveals natural patterns, dominant tendencies, tactical strengths, and weaknesses by giving full tactical freedom while a coach or third player records what shots are played. The data collected drives future training priorities and gives a clear picture of each player''s actual game versus their perceived game.', 'Synthesize all groundwork skills in a free-rally format while tracking specific metrics. This assessment drill reveals natural patterns, dominant tendencies, tactical strengths, and weaknesses by giving full tactical freedom while a coach or third player records what shots are played. The data collected drives future training priorities and gives a clear picture of each player''s actual game versus their perceived game.', 'Both players rally freely from the baseline using any shot, any direction, any spin. A third person (or one player on rest) tracks every shot: wing used, spin type, direction, depth, and outcome — error, in, or winner.', ARRAY['Play 5 points of free baseline rallying with full tactical freedom.','Observer records every shot: which wing, what spin, what direction, what outcome.','After 5 points, review the data together: patterns? most common errors? favorite zones?','Set a specific challenge for the next 5 points based on the data insights.','Play and track 4 rounds of 5 points, refining goals after each round.']::text[], ARRAY['Play your completely natural game — don''t change because of the tracking.','After reviewing the data, identify: which zone do you hit to 80% of the time? Is that tactically smart?','Is your error pattern random or consistent? Consistent errors reveal technical issues.','Notice: are you using the slice intentionally or only reactively when in trouble?','Does your forehand aggression match your self-perception? Most players are surprised.']::text[], ARRAY['Changing behavior because of observation — defeats the tracking purpose entirely.','Not using all three groundstrokes — using only one or two reveals a clear tactical gap.','Only looking at winners in the data — patterns and tendencies matter far more than outcomes.']::text[], ARRAY['Tracking only: observe two players rallying and track — great coaching and analysis tool.','Restriction based on data: if you went CC 90% of the time, the next round is DTL-only.','Full set tracking: track over an entire practice set — reveals match-play patterns under score pressure.']::text[], ARRAY['forehand','backhand','slice','assessment','tracking','intermediate','match-simulation']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":280,"y2":100},{"x1":200,"y1":70,"x2":120,"y2":820},{"x1":120,"y1":840,"x2":95,"y2":100},{"x1":200,"y1":60,"x2":200,"y2":810}],"areas":[{"x":280,"y":100,"r":30},{"x":95,"y":100,"r":30},{"x":200,"y":100,"r":30}]}'::jsonb),
  ('GW-050', 'Backhand Topspin Heavy Cross-Court: Consistency Under Spin', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Build a heavy topspin cross-court backhand that consistently lands deep — the shot used to dominate rallies from the backhand side. Heavy topspin gives both safety (the ball drops steeply) and tactical effectiveness (the high bounce pushes opponents back and disrupts their timing). This drill trains players to generate consistent heavy topspin from a comfortable position before adding movement and pressure.', 'Build a heavy topspin cross-court backhand that consistently lands deep — the shot used to dominate rallies from the backhand side. Heavy topspin gives both safety (the ball drops steeply) and tactical effectiveness (the high bounce pushes opponents back and disrupts their timing). This drill trains players to generate consistent heavy topspin from a comfortable position before adding movement and pressure.', 'Both players rally cross-court backhands. Player 1 focuses specifically on generating maximum topspin on every shot — each ball should clear the net by 3-4 feet and bounce up high. Player 2 feeds medium-paced balls to allow Player 1 full swing preparation.', ARRAY['Player 2 feeds medium-paced balls cross-court to Player 1''s backhand.','Player 1 hits every backhand with maximum topspin — heavy, high-arcing, deep.','Target: every ball should clear the net by 3-4 feet and land within 4 feet of the baseline.','After 10 minutes, Player 2 adds pace — Player 1 must generate topspin against faster balls.','Play 15 balls per set. Target: 12 out of 15 landing in the deep target zone.']::text[], ARRAY['Low backswing loop: drop the racket well below the contact point before driving upward.','Drive aggressively low-to-high through the ball — the upward motion generates all the topspin.','Finish high and across the body — racket ends above your head on the opposite side.','For two-handers: the dominant arm drives upward while the non-dominant arm guides.','The ball should bounce uncomfortably high for your opponent — if it doesn''t, add more brush.']::text[], ARRAY['Swinging too flat — ball has no topspin, goes long or sits up as an easy attack ball.','Incomplete follow-through — stopping early kills topspin and depth.','Short backswing preventing the low-to-high motion — produce more of a push than a drive.']::text[], ARRAY['Heavy topspin backhand plus redirect: alternate between heavy CC topspin and DTL redirect.','Both players hit heavy topspin CC — who can maintain the highest, deepest ball?','Add movement: Player 2 feeds wide — Player 1 must still generate heavy topspin from a wide position.']::text[], ARRAY['backhand','topspin','consistency','heavy spin','advanced','cross-court']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":120,"y1":840,"x2":295,"y2":100},{"x1":290,"y1":70,"x2":110,"y2":835}],"areas":[{"x":295,"y":110,"r":35},{"x":110,"y":820,"r":35}]}'::jsonb),
  ('SV-001', 'Flat First Serve Down the T: Deuce Court', 'Serve', 'Flat', 'serve', 'intermediate', 10, 1, 'individual', 'Develop a reliable flat first serve aimed at the T (center service line) from the deuce court. The T serve is the highest-percentage placement in the deuce court — it goes directly through the lowest part of the net at the center, gives the fewest angles to the returner, and sets up the inside-out forehand pattern on the next ball. This serve is used at the highest level of the game on every surface.', 'Develop a reliable flat first serve aimed at the T (center service line) from the deuce court. The T serve is the highest-percentage placement in the deuce court — it goes directly through the lowest part of the net at the center, gives the fewest angles to the returner, and sets up the inside-out forehand pattern on the next ball. This serve is used at the highest level of the game on every surface.', 'Player 1 serves from the deuce side baseline. Player 2 (or a cone) stands at the ad side of the opposite baseline as a visual target reference. Serve into the deuce service box only, targeting the T.', ARRAY['Player 1 takes a full basket of balls to the deuce side baseline.','Serve flat first serves aimed at the T — the center service line of the deuce service box.','Focus on hitting the T consistently — within 1 foot of the center service line.','Track makes and misses. Target: 7 out of 10 landing in the T zone.','Rest 60 seconds between rounds. Play 4 rounds.']::text[], ARRAY['Toss slightly more inside (to the left for right-handers) to hit the T without cutting across your body.','Swing through the ball with a flat, aggressive motion — this is not the time for spin.','Pronate the forearm through contact — the racket face turns from tilted to facing forward.','Drive upward with your legs — the power of a flat serve comes from the leg push, not the arm.','Follow through across your body completely — finish with the racket near your opposite hip.']::text[], ARRAY['Toss too far to the right — forces an awkward swing angle and misses wide.','Not pronating through contact — causes the serve to go left or into the net.','Arm-only swing without leg drive — serves lack power and depth.']::text[], ARRAY['Alternate T and wide serves within the same round — Player 2 must read which is coming.','Add a plus-one: after the T serve, feed Player 1 a ball to hit an inside-out forehand.','Score only T aces or unreturnable T serves — builds the habit of attacking the T.']::text[], ARRAY['serve','flat','deuce court','T serve','intermediate','placement']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":120,"y":60},"shots":[{"x1":240,"y1":850,"x2":200,"y2":370}],"areas":[{"x":200,"y":370,"r":22}],"cones":[{"x":200,"y":370}]}'::jsonb),
  ('SV-002', 'Wide Slice Serve: Deuce Court Puller', 'Serve', 'Slice', 'serve', 'intermediate', 12, 2, 'pairs', 'Develop a wide slice serve from the deuce court that curves out past the singles sideline and pulls the returner completely off the court. The wide slice serve is one of the most valuable serves in tennis because it creates extreme angles, forces weak returns from outside the court, and opens the entire deuce side for the next shot. On fast courts, it can be virtually unreturnable.', 'Develop a wide slice serve from the deuce court that curves out past the singles sideline and pulls the returner completely off the court. The wide slice serve is one of the most valuable serves in tennis because it creates extreme angles, forces weak returns from outside the court, and opens the entire deuce side for the next shot. On fast courts, it can be virtually unreturnable.', 'Player 1 serves from the deuce side baseline. Player 2 stands at the deuce side of the opposite baseline in the normal return position. Player 1 targets the wide service box corner — as close to the sideline as possible.', ARRAY['Player 1 serves a wide slice serve from the deuce court, aiming for the corner of the service box.','The serve must curve out toward the sideline — creating an angle that pulls Player 2 wide.','Player 2 returns from the wide position — Player 1 observes how wide Player 2 must move.','Track: how many slice serves land within 1 foot of the sideline? Target 6 out of 10.','After 10 serves, play out the full point — Player 1 exploits the open court with the next shot.']::text[], ARRAY['Toss slightly to the right (for right-handers) — further right than a T serve toss.','Brush across and around the right side of the ball at contact — 3 o''clock position on the ball.','The swing path goes across the ball, not through it — you are slicing the side, not driving forward.','Follow through to the left — the across motion creates the sideways curve.','The more spin you generate, the more the ball curves — work on brushing across aggressively.']::text[], ARRAY['Toss too far left — cannot get across the ball from this position, serve goes flat.','Swinging through the ball instead of across it — produces a flat wide serve that goes out.','Not enough brush — ball does not curve enough to create a wide angle.']::text[], ARRAY['Wide then body: alternate between wide slice and body serve — Player 2 must read the difference.','Wide plus inside-out: after the wide slice, Player 2 returns — Player 1 hits inside-out to the open court.','Speed versus angle: try maximum curve with less pace vs more pace with less curve — find the balance.']::text[], ARRAY['serve','slice','wide','deuce court','angle','intermediate']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":280,"y":60},"shots":[{"x1":240,"y1":850,"x2":320,"y2":390}],"areas":[{"x":320,"y":390,"r":22}],"cones":[{"x":320,"y":390}]}'::jsonb),
  ('SV-003', 'Kick Serve to the Backhand: Ad Court', 'Serve', 'Kick', 'serve', 'advanced', 12, 2, 'pairs', 'Develop a reliable kick serve targeted at the returner''s backhand in the ad court. The kick serve bounces high and kicks away from the returner, forcing them to hit a backhand at an uncomfortable shoulder height. It is the most widely used second serve at the professional level because its topspin brings it into the court reliably while the high kick makes it difficult to attack. This is the second serve that changes matches.', 'Develop a reliable kick serve targeted at the returner''s backhand in the ad court. The kick serve bounces high and kicks away from the returner, forcing them to hit a backhand at an uncomfortable shoulder height. It is the most widely used second serve at the professional level because its topspin brings it into the court reliably while the high kick makes it difficult to attack. This is the second serve that changes matches.', 'Player 1 serves from the ad side baseline. Player 2 stands at the ad side of the opposite baseline in the return position. Player 1 targets the backhand corner of the ad service box — the ball should kick high and move further outside after the bounce.', ARRAY['Player 1 serves a kick serve from the ad court, targeting Player 2''s backhand.','The ball should bounce well above waist height — ideally at shoulder height.','Player 2 attempts to return — Player 1 observes the quality of the return forced by the kick.','Track: how many kick serves bounce above the returner''s waist? Target 7 out of 10.','Play out the full point after each kick serve — is the kick serve setting up an easy third ball?']::text[], ARRAY['Toss slightly behind your head and to the left (for right-handers) — behind you, not in front.','Swing from 7 o''clock to 1 o''clock across the back of the ball — this is the topspin/side-spin motion.','Snap your wrist through contact — the wrist snap accelerates the racket head and creates spin.','Your body should arch and turn as you swing — the kick serve uses the whole body.','The ball should rise after the bounce, not fall — if it falls, you need more topspin.']::text[], ARRAY['Toss too far in front — cannot swing from 7 to 1 from this position, produces a flat serve.','Swinging straight down instead of across — produces topspin without kick, ball stays low.','Not arching the back enough — limits the upward snap through the ball.']::text[], ARRAY['Kick serve to the body: same motion, different target — jams the returner on their hip.','Wide kick in the ad court: kick serves can also go wide — pulls the returner off the court.','Kick second serve pressure: serve one flat first serve, then one kick second — full serve sequence.']::text[], ARRAY['serve','kick','ad court','backhand','advanced','second serve']::text[], 'json', '{"p1":{"x":160,"y":860},"p2":{"x":280,"y":60},"shots":[{"x1":160,"y1":850,"x2":250,"y2":385}],"areas":[{"x":250,"y":385,"r":25}],"cones":[{"x":250,"y":385}]}'::jsonb),
  ('SV-004', 'Body Serve: Jam the Returner', 'Serve', 'Flat', 'serve', 'intermediate', 10, 2, 'pairs', 'Develop the body serve — aimed directly at the returner''s hip or dominant shoulder to jam their swing. The body serve is one of the most underused and underestimated serves in tennis. It forces the returner to take a large step backward or sideways before hitting, which removes power and often produces a weak, floating return. It works on both deuce and ad courts and is extremely effective against players who like to step into the service box to return.', 'Develop the body serve — aimed directly at the returner''s hip or dominant shoulder to jam their swing. The body serve is one of the most underused and underestimated serves in tennis. It forces the returner to take a large step backward or sideways before hitting, which removes power and often produces a weak, floating return. It works on both deuce and ad courts and is extremely effective against players who like to step into the service box to return.', 'Player 1 serves from both the deuce and ad sides. Player 2 stands in the normal return position. Player 1 targets the body — at the returner''s hip or dominant shoulder — rather than the corners.', ARRAY['Player 1 serves from the deuce court first, targeting Player 2''s dominant hip or shoulder.','The ball should arrive directly at Player 2''s body — forcing them to move out of the way.','Observe Player 2''s return: are they cramped? Did they have to back off?','After 8 deuce-court body serves, switch to the ad court and repeat.','Track: what percentage of body serves force a weak or late return? Target: 60%+.']::text[], ARRAY['The target is the inside hip — for a right-hander returning in the deuce court, aim at their left hip.','Use a flat or light slice motion — the body serve does not need heavy spin to be effective.','Disguise: the toss and preparation should look identical to your T or wide serve.','Pace is important: a fast body serve gives less time to move, making it more effective.','Use the body serve when the returner is leaning or cheating to a corner — it catches them moving.']::text[], ARRAY['Serving too close to the center — misses the jam effect, Player 2 can swing freely.','Telegraphing the body serve with a different toss or stance.','Using the body serve too predictably — must be mixed in with corner serves.']::text[], ARRAY['Body serve then open court: after the weak return, attack the open court immediately.','Guess game: Player 2 guesses ''body'' or ''corner'' before the serve — Player 1 must mix well.','Doubles body serve: target the opponent''s body to prevent interception from the net player.']::text[], ARRAY['serve','body','flat','tactical','intermediate','both courts']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":120,"y":60},"shots":[{"x1":240,"y1":850,"x2":150,"y2":375}],"areas":[{"x":150,"y":375,"r":22}],"cones":[{"x":150,"y":375}]}'::jsonb),
  ('SV-005', 'Second Serve Consistency Under Pressure', 'Serve', 'Kick', 'serve', 'intermediate', 15, 2, 'pairs', 'Build a reliable, consistent second serve under mental pressure — the single most important skill in the entire service game. A weak second serve gives the opponent a free attack ball and shifts all momentum. This drill trains second serve reliability specifically, targeting both the technique and the mental composure required to hit a quality second serve when it counts most in a match.', 'Build a reliable, consistent second serve under mental pressure — the single most important skill in the entire service game. A weak second serve gives the opponent a free attack ball and shifts all momentum. This drill trains second serve reliability specifically, targeting both the technique and the mental composure required to hit a quality second serve when it counts most in a match.', 'Player 1 serves second serves only — no first serves during this drill. Player 2 returns aggressively. Player 1 must land all serves in the service box with enough spin and pace to prevent an easy attack. There is no room for double faults.', ARRAY['Player 1 serves only second serves — focus on spin and reliability over pace.','Player 2 returns aggressively — attacks any weak second serve.','Track double faults separately from in-play misses — double faults are especially costly.','Score: +1 for each second serve that lands in, -3 for each double fault.','Play 30 second serves per set. Target: 25+ in with 0 double faults.']::text[], ARRAY['Spin is the safety net — kick or slice spin brings the ball down into the box reliably.','Never go for pace on a second serve — spin first, pace second.','Commit fully to the motion — hesitation causes double faults more than anything else.','Breathe before the ball toss — tension tightens the arm and kills spin.','Trust your technique — second serves fail when players change their swing under pressure.']::text[], ARRAY['Going for too much pace on the second serve — doubles fault or floats into the middle.','Hesitating mid-swing — the most common cause of double faults.','Changing the motion under pressure — consistency requires exactly the same motion every time.']::text[], ARRAY['Pressure sets: Player 1 starts the second serve at deuce — must get 2 in a row to ''win''.','Consequence game: Player 1 owes 5 push-ups for every double fault — real stakes.','Locate the second serve: must alternate between kick to backhand and slice wide — both must land.']::text[], ARRAY['serve','second serve','consistency','kick','pressure','intermediate']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":850,"x2":200,"y2":390}],"areas":[{"x":150,"y":390,"r":30},{"x":250,"y":390,"r":30}]}'::jsonb)
